export function PrimaryButton({
  label = "{{label}}",
  size = "{{size}}",
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  const lg = size === "lg";
  return (
    <button
      type="button"
      disabled={disabled}
      style={{
        padding: lg ? "15px 28px" : "12px 22px",
        fontSize: lg ? 16 : 15,
        borderRadius: radius,
        border: "none",
        background: bg,
        color: "#FAF7F2",
        fontWeight: 700,
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.45 : 1,
      }}
    >
      {label}
    </button>
  );
}
